# Aggressively patch DATA_DIR to find where the data actually lives
import sys as _patch_sys, os as _patch_os

def _patch_data_dir():
    _mod = _patch_sys.modules[__name__]
    orig = getattr(_mod, "DATA_DIR", "/data/adbench")
    if _patch_os.path.isdir(orig):
        return

    target_files = {"6_cardio.npz", "38_thyroid.npz", "30_satellite.npz", "32_shuttle.npz"}

    def _check_dir(d):
        try:
            return _patch_os.path.isdir(d) and bool(target_files & set(_patch_os.listdir(d)))
        except Exception:
            return False

    # Try direct paths
    for d in [
        "/data/adbench", "/data",
        _patch_os.path.join(_patch_os.path.expanduser("~"), "adbench"),
        _patch_os.path.join(_patch_os.path.expanduser("~"), "data", "adbench"),
        _patch_os.path.join(_patch_os.path.expanduser("~"), "data"),
        "/tmp/adbench", "/tmp/data/adbench", "/tmp/data",
        "/workspace/adbench", "/workspace/data",
        "/mnt/adbench", "/mnt/data/adbench",
        _patch_os.path.abspath("./adbench"),
        _patch_os.path.abspath("./data/adbench"),
        _patch_os.path.abspath("./data"),
    ]:
        if _check_dir(d):
            _mod.DATA_DIR = d
            return

    # Walk filesystem
    for root in ["/home", "/tmp", "/workspace", "/mnt", "/data", "/opt", "/srv"]:
        if not _patch_os.path.isdir(root):
            continue
        try:
            for r, ds, fs in _patch_os.walk(root, topdown=True):
                depth = len(r.replace(root, "").split(_patch_os.sep)) - 1
                if depth > 3:
                    ds.clear()
                    continue
                if target_files & set(f for f in fs if f.endswith(".npz")):
                    _mod.DATA_DIR = r
                    return
        except (PermissionError, OSError):
            continue

